arguments.file_text:
@page "/dispatcher"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@attribute [Authorize(Roles = "Dispatcher")]
@rendermode InteractiveAuto
@inject HttpClient Http

<PageTitle>Dispatcher Dashboard</PageTitle>

<h3 class="mb-4">📦 Dispatcher Dashboard</h3>

<div class="row mb-3">
    <div class="col-md-4">
        <input class="form-control" placeholder="Filter by tracking #, destination, or recipient..."
               @bind="filterText" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="statusFilter">
            <option value="">All Statuses</option>
            @foreach (var s in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@s">@s</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button class="btn btn-primary w-100" @onclick="LoadShipments">
            🔄 Refresh
        </button>
    </div>
    <div class="col-md-3">
        <button class="btn btn-success w-100" @onclick="() => showCreateForm = !showCreateForm">
            ➕ New Shipment
        </button>
    </div>
</div>

@if (showCreateForm)
{
    <div class="card mb-4">
        <div class="card-body">
            <h5 class="card-title">Create New Shipment</h5>
            <div class="row g-2">
                <div class="col-md-3">
                    <input class="form-control" placeholder="Tracking #" @bind="newShipment.TrackingNumber" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" placeholder="Recipient Name" @bind="newShipment.RecipientName" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" placeholder="Customer Email" @bind="newShipment.CustomerEmail" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" placeholder="Description" @bind="newShipment.Description" />
                </div>
                <div class="col-md-2">
                    <input type="date" class="form-control" @bind="newShipment.EstimatedDelivery" />
                </div>
                <div class="col-md-1">
                    <button class="btn btn-primary" @onclick="CreateShipment">Create</button>
                </div>
            </div>
            @if (!string.IsNullOrEmpty(createError))
            {
                <div class="alert alert-danger mt-2">@createError</div>
            }
        </div>
    </div>
}

@if (loading)
{
    <p><em>Loading shipments...</em></p>
}
else if (shipments is null)
{
    <div class="alert alert-danger">Failed to load shipments.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Recipient</th>
                    <th>Status</th>
                    <th>Shipped</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td><strong>@s.TrackingNumber</strong></td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td>@s.RecipientName</td>
                        <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                        <td>@s.ShippedDate.ToString("MMM dd, yyyy")</td>
                        <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                        <td>
                            <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
                                    value="@s.Status"
                                    @onchange="(e) => UpdateStatus(s, e)">
                                @foreach (var st in Enum.GetValues<ShipmentStatus>())
                                {
                                    <option value="@st" selected="@(st == s.Status)">@st</option>
                                }
                            </select>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
    <p class="text-muted">Showing @FilteredShipments.Count() of @shipments.Count shipments</p>
}

@code {
    private List<ShipmentDto>? shipments;
    private bool loading = true;
    private string filterText = "";
    private string statusFilter = "";
    private bool showCreateForm;
    private ShipmentDto newShipment = new() { ShippedDate = DateTime.UtcNow, EstimatedDelivery = DateTime.UtcNow.AddDays(5) };
    private string? createError;

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        loading = true;
        try
        {
            shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments");
        }
        catch
        {
            shipments = null;
        }
        loading = false;
    }

    private IEnumerable<ShipmentDto> FilteredShipments =>
        (shipments ?? []).Where(s =>
        {
            if (!string.IsNullOrEmpty(statusFilter) && s.Status.ToString() != statusFilter)
                return false;
            if (!string.IsNullOrEmpty(filterText))
            {
                var ft = filterText.ToLowerInvariant();
                return s.TrackingNumber.Contains(ft, StringComparison.OrdinalIgnoreCase)
                    || s.Destination.Contains(ft, StringComparison.OrdinalIgnoreCase)
                    || s.RecipientName.Contains(ft, StringComparison.OrdinalIgnoreCase);
            }
            return true;
        });

    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            var response = await Http.PutAsJsonAsync($"/api/shipments/{shipment.Id}/status",
                new UpdateShipmentStatusRequest { NewStatus = newStatus });
            if (response.IsSuccessStatusCode)
            {
                shipment.Status = newStatus;
                if (newStatus == ShipmentStatus.Delivered)
                    shipment.ActualDelivery = DateTime.UtcNow;
            }
        }
    }

    private async Task CreateShipment()
    {
        createError = null;
        var response = await Http.PostAsJsonAsync("/api/shipments", newShipment);
        if (response.IsSuccessStatusCode)
        {
            showCreateForm = false;
            newShipment = new() { ShippedDate = DateTime.UtcNow, EstimatedDelivery = DateTime.UtcNow.AddDays(5) };
            await LoadShipments();
        }
        else
        {
            createError = $"Failed to create shipment: {response.StatusCode}";
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Cancelled => "bg-dark",
        _ => "bg-secondary"
    };
}

