@page "/track"
@using ShipmentTracker.Client.Models
@rendermode InteractiveAuto
@inject HttpClient Http

<PageTitle>Track a Shipment</PageTitle>

<h3 class="mb-4">🔍 Track a Shipment</h3>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input class="form-control" placeholder="Enter tracking number (e.g., ST-100001)"
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="TrackShipment" disabled="@searching">
                @(searching ? "Searching..." : "Track")
            </button>
        </div>
    </div>
</div>

@if (notFound)
{
    <div class="alert alert-warning">
        No shipment found with tracking number <strong>@searchedNumber</strong>. Please check and try again.
    </div>
}
else if (shipment is not null)
{
    <div class="card" style="max-width: 600px;">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h5 class="mb-0">@shipment.TrackingNumber</h5>
            <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-6">
                    <p><strong>Description:</strong><br/>@shipment.Description</p>
                    <p><strong>Recipient:</strong><br/>@shipment.RecipientName</p>
                </div>
                <div class="col-6">
                    <p><strong>Origin:</strong><br/>@shipment.Origin</p>
                    <p><strong>Destination:</strong><br/>@shipment.Destination</p>
                </div>
            </div>
            <hr/>

            <!-- Progress tracker -->
            <div class="mb-3">
                <h6>Shipment Progress</h6>
                <div class="progress" style="height: 25px;">
                    <div class="progress-bar @GetProgressBarClass(shipment.Status)"
                         role="progressbar"
                         style="width: @(GetProgressPercent(shipment.Status))%">
                        @shipment.Status
                    </div>
                </div>
            </div>

            <div class="row text-center">
                <div class="col-4">
                    <small class="text-muted">Shipped</small><br/>
                    <strong>@shipment.ShippedDate.ToString("MMM dd")</strong>
                </div>
                <div class="col-4">
                    <small class="text-muted">Est. Delivery</small><br/>
                    <strong class="@(shipment.EstimatedDelivery < DateTime.UtcNow && shipment.Status != ShipmentStatus.Delivered ? "text-danger" : "")">
                        @shipment.EstimatedDelivery.ToString("MMM dd")
                    </strong>
                </div>
                <div class="col-4">
                    @if (shipment.ActualDelivery.HasValue)
                    {
                        <small class="text-muted">Delivered</small><br/>
                        <strong class="text-success">@shipment.ActualDelivery.Value.ToString("MMM dd")</strong>
                    }
                    else
                    {
                        <small class="text-muted">Days Left</small><br/>
                        @{
                            var daysLeft = (shipment.EstimatedDelivery - DateTime.UtcNow).Days;
                        }
                        <strong class="@(daysLeft < 0 ? "text-danger" : "")">
                            @(daysLeft < 0 ? "Overdue" : $"{daysLeft} days")
                        </strong>
                    }
                </div>
            </div>
        </div>
    </div>
}

@code {
    private string trackingNumber = "";
    private string searchedNumber = "";
    private ShipmentDto? shipment;
    private bool notFound;
    private bool searching;

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        searching = true;
        notFound = false;
        shipment = null;
        searchedNumber = trackingNumber.Trim();

        try
        {
            var response = await Http.GetAsync($"/api/shipments/track/{Uri.EscapeDataString(searchedNumber)}");
            if (response.IsSuccessStatusCode)
                shipment = await response.Content.ReadFromJsonAsync<ShipmentDto>();
            else
                notFound = true;
        }
        catch
        {
            notFound = true;
        }
        searching = false;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Cancelled => "bg-dark",
        _ => "bg-secondary"
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Cancelled => "bg-dark",
        _ => "bg-primary"
    };

    private static int GetProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 25,
        ShipmentStatus.InTransit => 50,
        ShipmentStatus.OutForDelivery => 75,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Delayed => 50,
        ShipmentStatus.Cancelled => 100,
        _ => 0
    };
}

