@page "/my-shipments"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@attribute [Authorize]
@rendermode InteractiveAuto
@inject HttpClient Http

<PageTitle>My Shipments</PageTitle>

<h3 class="mb-4">📋 My Shipments</h3>

@if (loading)
{
    <p><em>Loading your shipments...</em></p>
}
else if (shipments is null || shipments.Count == 0)
{
    <div class="alert alert-info">No shipments found for your account.</div>
}
else
{
    <div class="row">
        @foreach (var s in shipments)
        {
            <div class="col-md-6 col-lg-4 mb-4">
                <div class="card h-100 @(s.Status == ShipmentStatus.Delivered ? "border-success" : s.Status == ShipmentStatus.Delayed ? "border-danger" : "")">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>@s.TrackingNumber</strong>
                        <span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span>
                    </div>
                    <div class="card-body">
                        <p class="card-text">
                            <strong>Description:</strong> @s.Description<br/>
                            <strong>From:</strong> @s.Origin<br/>
                            <strong>To:</strong> @s.Destination<br/>
                            <strong>Recipient:</strong> @s.RecipientName
                        </p>
                        <hr/>
                        <p class="mb-1">
                            <strong>Shipped:</strong> @s.ShippedDate.ToString("MMM dd, yyyy")
                        </p>
                        <p class="mb-1">
                            <strong>Est. Delivery:</strong>
                            <span class="@(s.EstimatedDelivery < DateTime.UtcNow && s.Status != ShipmentStatus.Delivered ? "text-danger fw-bold" : "")">
                                @s.EstimatedDelivery.ToString("MMM dd, yyyy")
                            </span>
                        </p>
                        @if (s.ActualDelivery.HasValue)
                        {
                            <p class="mb-0 text-success">
                                <strong>Delivered:</strong> @s.ActualDelivery.Value.ToString("MMM dd, yyyy")
                            </p>
                        }
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private List<ShipmentDto>? shipments;
    private bool loading = true;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments/my");
        }
        catch
        {
            shipments = null;
        }
        loading = false;
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Cancelled => "bg-dark",
        _ => "bg-secondary"
    };
}

@page "/track"
@using ShipmentTracker.Client.Models
@rendermode InteractiveAuto
@inject HttpClient Http

<PageTitle>Track a Shipment</PageTitle>

<h3 class="mb-4">🔍 Track a Shipment</h3>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input class="form-control" placeholder="Enter tracking number (e.g., ST-100001)"
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="TrackShipment" disabled="@searching">
                @(searching ? "Searching..." : "Track")
            </button>
        </div>
    </div>
</div>

@if (notFound)
{
    <div class="alert alert-warning">
        No shipment found with tracking number <strong>@searchedNumber</strong>. Please check and try again.
    </div>
}
else if (shipment is not null)
{
    <div class="card" style="max-width: 600px;">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h5 class="mb-0">@shipment.TrackingNumber</h5>
            <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-6">
                    <p><strong>Description:</strong><br/>@shipment.Description</p>
                    <p><strong>Recipient:</strong><br/>@shipment.RecipientName</p>
                </div>
                <div class="col-6">
                    <p><strong>Origin:</strong><br/>@shipment.Origin</p>
                    <p><strong>Destination:</strong><br/>@shipment.Destination</p>
                </div>
            </div>
            <hr/>

            <!-- Progress tracker -->
            <div class="mb-3">
                <h6>Shipment Progress</h6>
                <div class="progress" style="height: 25px;">
                    <div class="progress-bar @GetProgressBarClass(shipment.Status)"
                         role="progressbar"
                         style="width: @(GetProgressPercent(shipment.Status))%">
                        @shipment.Status
                    </div>
                </div>
            </div>

            <div class="row text-center">
                <div class="col-4">
                    <small class="text-muted">Shipped</small><br/>
                    <strong>@shipment.ShippedDate.ToString("MMM dd")</strong>
                </div>
                <div class="col-4">
                    <small class="text-muted">Est. Delivery</small><br/>
                    <strong class="@(shipment.EstimatedDelivery < DateTime.UtcNow && shipment.Status != ShipmentStatus.Delivered ? "text-danger" : "")">
                        @shipment.EstimatedDelivery.ToString("MMM dd")
                    </strong>
                </div>
                <div class="col-4">
                    @if (shipment.ActualDelivery.HasValue)
                    {
                        <small class="text-muted">Delivered</small><br/>
                        <strong class="text-success">@shipment.ActualDelivery.Value.ToString("MMM dd")</strong>
                    }
                    else
                    {
                        <small class="text-muted">Days Left</small><br/>
                        @{
                            var daysLeft = (shipment.EstimatedDelivery - DateTime.UtcNow).Days;
                        }
                        <strong class="@(daysLeft < 0 ? "text-danger" : "")">
                            @(daysLeft < 0 ? "Overdue" : $"{daysLeft} days")
                        </strong>
                    }
                </div>
            </div>
        </div>
    </div>
}

@code {
    private string trackingNumber = "";
    private string searchedNumber = "";
    private ShipmentDto? shipment;
    private bool notFound;
    private bool searching;

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        searching = true;
        notFound = false;
        shipment = null;
        searchedNumber = trackingNumber.Trim();

        try
        {
            var response = await Http.GetAsync($"/api/shipments/track/{Uri.EscapeDataString(searchedNumber)}");
            if (response.IsSuccessStatusCode)
                shipment = await response.Content.ReadFromJsonAsync<ShipmentDto>();
            else
                notFound = true;
        }
        catch
        {
            notFound = true;
        }
        searching = false;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Cancelled => "bg-dark",
        _ => "bg-secondary"
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Cancelled => "bg-dark",
        _ => "bg-primary"
    };

    private static int GetProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 25,
        ShipmentStatus.InTransit => 50,
        ShipmentStatus.OutForDelivery => 75,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Delayed => 50,
        ShipmentStatus.Cancelled => 100,
        _ => 0
    };
}

